		total += uint64(k)
	}
	// Now handle numbers with maxBits bits
	// The first bit is 1, the rest maxBits-1 bits
	// We need exactly one 0 among the remaining maxBits-1 bits
	// So we choose one position (from maxBits-1 positions) to be 0, rest are 1
	// But the number must be <= n
	// Generate all such numbers and count how many are <= n
	// The number is (1 << (maxBits-1)) | (mask with one 0)
	// Actually, the number is: first bit 1, then maxBits-1 bits with exactly one 0
	// So the number = (1 << (maxBits-1)) + (all ones in maxBits-1 bits) - (1 << i) for i in 0..maxBits-2
	// = (1 << (maxBits-1)) + ((1 << (maxBits-1)) - 1) - (1 << i)
	// = (1 << maxBits) - 1 - (1 << i)
	// We need this <= n
	// So (1 << maxBits) - 1 - (1 << i) <= n
	// => (1 << i) >= (1 << maxBits) - 1 - n
	// => i >= log2((1 << maxBits) - 1 - n)
	// But let's just iterate
	base := uint64(1) << (maxBits - 1)
	// The number has maxBits bits, first is 1
	// Remaining maxBits-1 bits: exactly one 0
	// So the value is base + (base - 1) - (1 << i) = (base << 1) - 1 - (1 << i) for i in 0..maxBits-2
	// Wait, base = 1 << (maxBits-1), so base-1 = (1 << (maxBits-1)) - 1
	// Number = base + (base - 1) - (1 << i) = 2*base - 1 - (1 << i) = (1 << maxBits) - 1 - (1 << i)
	// We need (1 << maxBits) - 1 - (1 << i) <= n
	// => (1 << i) >= (1 << maxBits) - 1 - n
	threshold := (uint64(1) << maxBits) - 1 - n
	for i := 0; i < maxBits-1; i++ {
		if (uint64(1) << i) >= threshold {
			total++
		}
	}
	return total
